// Maintainer-reviewed application adapter, never generated by a model.
// Runtime dependencies are shared with the trusted original installation.
// This is process/copy isolation, NOT an OS sandbox or an immutable dependency mount.
import { symlink } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
import { createServer } from 'node:http';
export async function start({root,originRoot}) {
  await symlink(join(originRoot,'node_modules'),join(root,'node_modules'),process.platform==='win32'?'junction':'dir').catch(e=>{if(e.code!=='EEXIST')throw e;});
  const require=createRequire(join(originRoot,'package.json'));
  const pkg=require('./package.json');
  if(pkg.dependencies.next) {
    const next=require('next'),app=next({dev:true,dir:root,webpack:true,hostname:'127.0.0.1'});
    await app.prepare();const handle=app.getRequestHandler();
    const server=createServer((req,res)=>handle(req,res));
    await new Promise(r=>server.listen(0,'127.0.0.1',r));
    return {url:`http://127.0.0.1:${server.address().port}`,async stop(){server.closeAllConnections();await new Promise(r=>server.close(r));await app.close();}};
  }
  const {createServer:makeVite}=await import(pathToFileURL(require.resolve('vite')).href);
  const server=await makeVite({root,configFile:join(root,'vite.config.js'),server:{host:'127.0.0.1',port:0,strictPort:false,hmr:false},logLevel:'error'});
  await server.listen();
  return {url:`http://127.0.0.1:${server.httpServer.address().port}`,stop:()=>server.close()};
}
